import Foundation

extension AccessibilityGuides {
    static let disability = DirectoryGuide(
        cardSummary: .init(ukrainian: "Австрійське посвідчення, записи, оскарження й паркування", german: "Behindertenpass, Eintragungen, Rechtsmittel und Parken"),
        introduction: .init(ukrainian: "Спочатку визначте, який саме доказ потрібен: Behindertenpass, додатковий запис або окреме рішення для роботи. Український документ додайте до заяви, але австрійське право оцінюють окремо.", german: "Zuerst klären, welcher Nachweis benötigt wird: Behindertenpass, Zusatzeintragung oder eigener Bescheid fürs Arbeitsleben. Ukrainische Unterlagen beilegen; der österreichische Anspruch wird gesondert geprüft."),
        sections: [
            .init("eligibility", "person.crop.rectangle", "Кому доступний Behindertenpass", "Wer einen Behindertenpass erhalten kann", "Право на Behindertenpass зазвичай вимагає встановленого в Австрії ступеня інвалідності щонайменше 50 % і місця проживання або звичайного перебування тут. Подайте заяву до земельного відділення Sozialministeriumservice з медичними висновками та документом особи; запитайте, чи потрібен переклад іноземних висновків. Якщо австрійського рішення про ступінь ще немає, служба організує оцінювання. Заява й видача безплатні.", "Für den Behindertenpass sind grundsätzlich mindestens 50 % festgestellter Grad der Behinderung sowie Wohnsitz oder gewöhnlicher Aufenthalt in Österreich nötig. Antrag mit Befunden und Identitätsnachweis bei der Landesstelle stellen; Übersetzungsbedarf ausländischer Befunde erfragen. Liegt noch keine österreichische Feststellung vor, veranlasst die Stelle eine Begutachtung. Antrag und Ausstellung sind kostenlos.", source: pass),
            .init("decision", "doc.text.magnifyingglass", "Перевірте рішення", "Bescheid prüfen", "Після відповіді звірте встановлений ступінь, строк дії та обґрунтування зі своїми висновками. Якщо ви не згодні, збережіть дату вручення Bescheid: Sozialministeriumservice вказує шість тижнів для оскарження після вручення. Дотримуйтеся інструкції саме у вашому рішенні та додайте конкретні пропущені обмеження чи нові медичні докази.", "Nach der Antwort Grad, Gültigkeit und Begründung mit den eigenen Befunden vergleichen. Bei Widerspruch das Zustelldatum des Bescheids sichern: Das Sozialministeriumservice nennt sechs Wochen ab Zustellung für ein Rechtsmittel. Der Belehrung im eigenen Bescheid folgen und konkret übersehene Einschränkungen oder neue Befunde belegen.", source: pass),
            .init("entries", "list.bullet.rectangle", "Додаткові записи — окрема заявка", "Zusatzeintragungen eigens beantragen", "Для неможливості користуватися громадським транспортом, потреби в супроводі, права на знижку проїзду або сліпоти є різні додаткові записи в Behindertenpass. Перевірте на офіційній сторінці умови саме потрібного запису та подайте окремий запит із відповідними висновками. Сам ступінь 50 % не означає автоматично жодного з цих записів.", "Für Unzumutbarkeit öffentlicher Verkehrsmittel, Begleitperson, Fahrpreisermäßigung oder Blindheit gibt es unterschiedliche Zusatzeintragungen im Behindertenpass. Voraussetzungen des benötigten Eintrags auf der amtlichen Seite prüfen und ihn mit passenden Befunden eigens beantragen. Ein Grad von 50 % bewirkt keinen dieser Einträge automatisch.", source: entries),
            .init("parking", "parkingsign.circle", "Окремо оформіть Parkausweis", "Parkausweis gesondert beantragen", "Для паркувального посвідчення за § 29b StVO потрібен Behindertenpass із записом про неможливість користування громадським транспортом або сліпоту. Заява до Sozialministeriumservice і видача безплатні. Сам Behindertenpass не дозволяє зайняти спеціальне місце. Якщо маєте іноземний паркувальний документ, перевірте його чинність в Австрії перед використанням.", "Für den Parkausweis nach § 29b StVO ist ein Behindertenpass mit Eintrag zur Unzumutbarkeit öffentlicher Verkehrsmittel oder Blindheit nötig. Antrag und Ausstellung beim Sozialministeriumservice sind kostenlos. Der Behindertenpass allein berechtigt nicht zum Behindertenparkplatz. Bei ausländischem Parkausweis vor Nutzung dessen Anerkennung in Österreich prüfen.", source: parking),
            .init("employment-status", "briefcase", "Для захисту на роботі потрібне інше рішення", "Für Arbeitsschutz ist ein anderer Bescheid nötig", "Behindertenpass не є рішенням про статус begünstigte Behinderte і сам не надає спеціального захисту від звільнення. Якщо потрібні трудові права за цим статусом, перевірте його окремі умови та подайте окрему заяву до Sozialministeriumservice. Для громадян третіх країн служба також перевіряє право проживати й працювати в Австрії; уточніть це до подання.", "Ein Behindertenpass ist kein Bescheid über die Zugehörigkeit zum Kreis der begünstigten Behinderten und begründet allein keinen besonderen Kündigungsschutz. Für diese arbeitsrechtlichen Vorteile die eigenen Voraussetzungen prüfen und einen gesonderten Antrag beim Sozialministeriumservice stellen. Bei Drittstaatsangehörigen wird auch das Recht auf Aufenthalt und Arbeit geprüft; dies vorab klären.", source: employmentStatus)
        ], sources: [pass, entries, parking, employmentStatus]
    )
